<template><view class="page"><PageHead title="确认订单"/><view class="content"><view v-if="pending" class="card"><view class="bold">上次订单等待确认</view><view class="subtitle">网络异常时订单可能已提交。请先查询结果或继续提交原订单，避免重复下单。</view><button class="btn" :disabled="busy" @click="recover(false)">查询订单结果</button><button class="btn light" :disabled="busy" @click="recover(true)">继续提交原订单</button></view><view class="chips" style="margin-bottom:25rpx"><view :class="['chip',{selected:type==='DELIVERY'}]" @click="type='DELIVERY'">外卖配送</view><view :class="['chip',{selected:type==='PICKUP'}]" @click="type='PICKUP'">到店自取</view></view><view v-if="type==='DELIVERY'" class="card address" @click="go('addresses/index?select=1')"><template v-if="address"><view class="between"><text class="bold">{{address.detail}}</text><text>›</text></view><view class="subtitle">{{address.contact}} {{address.phone}}</view></template><template v-else><view class="bold">＋ 添加收货地址</view><view class="subtitle">送到宿舍，也送来一份好心情</view></template></view><view v-else class="card"><view class="bold">到店凭取餐码领取</view><view class="subtitle">{{store.name}} · {{store.zone}}</view></view>
<view v-if="store.reservation_enabled" class="card"><view class="bold">用餐时间（北京时间）</view><picker :range="slotLabels" @change="scheduledAt=Number($event.detail.value)?slots[Number($event.detail.value)-1].value:''"><view class="field">{{slots.find(s=>s.value===scheduledAt)?.label||'尽快制作'}} ›</view></picker><view class="subtitle">预约库存现在预留，请15分钟内模拟支付；商家到备餐时间后接单。</view></view><view class="card"><view class="bold">{{store.name}}</view><view class="divider"/><view v-for="p in cart.items" :key="p.lineKey||p.id" class="item"><image :src="p.image" mode="aspectFill"/><view class="item-copy"><view>{{p.name}}</view><view class="small muted">{{p.option_text}}</view><view class="small muted">×{{p.quantity}}</view></view><text>¥{{money(p.price*p.quantity)}}</text></view><view class="divider"/><view class="between small"><text>配送费</text><text>¥{{money(fee)}}</text></view><view class="between coupon-row" @click="chooseCoupon"><text>优惠券</text><text class="link">{{coupon?'− ¥'+money(discount):'选择优惠券'}} ›</text></view><view class="between"><text class="bold">合计</text><text class="price">¥{{money(total)}}</text></view></view>
<view class="card"><text class="label">给商家的备注</text><textarea v-model="remark" placeholder="口味偏好、餐具数量等（选填）" maxlength="200" class="remark"/></view><view class="small muted">模拟支付仅用于体验，不会产生真实扣款。订单提交后请在15分钟内完成支付。</view><view v-if="blocked" class="error">{{blocked}}</view><view v-if="error" class="error">{{error}}</view></view><view class="fixed-action between"><view><text class="small">待支付 </text><text class="price">¥{{money(total)}}</text></view><button class="btn" :loading="busy" :disabled="busy||loading||pending||!!blocked||!store.id||!cart.items.length" @click="submit">提交订单</button></view></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import PageHead from '../../components/PageHead.vue';import {state,request,ensureLogin,cart,clearCart,saveCart,money,go,key,toast} from '../../lib/api';
import {distanceMeters} from '../../lib/geo.mjs';import {queryString} from '../../lib/paged-catalog.mjs';import {reconcileCart} from '../../lib/checkout.mjs';
import {intents,memberIdentity,recoverOrder,openConfirmedOrder} from '../../lib/recovery';import {cartSignature} from '../../lib/order-intent.mjs';
const pending=ref(!!intents.read()),slots=ref([]),scheduledAt=ref(''),slotLabels=computed(()=>['尽快制作',...slots.value.map(s=>s.label)]);async function recover(retry){busy.value=true;error.value='';try{await memberIdentity();if(!await recoverOrder(retry))error.value='暂未查到订单，可继续提交原订单'}catch(e){error.value=e.message}finally{pending.value=!!intents.read();busy.value=false;if(!pending.value&&!store.value.id)await loadCheckout()}}
const loading=ref(false);const store=ref({}),address=ref(null),coupons=ref([]),coupon=ref(null),type=ref('DELIVERY'),remark=ref(''),busy=ref(false),error=ref('');let requestKey=key(),lastBody='';const subtotal=computed(()=>cart.items.reduce((s,p)=>s+p.price*p.quantity,0)),fee=computed(()=>type.value==='DELIVERY'?(store.value.delivery_fee||0):0),discount=computed(()=>coupon.value?Math.min(subtotal.value,coupon.value.amount):0),total=computed(()=>subtotal.value+fee.value-discount.value);
const blocked=computed(()=>{if(store.value.open_now===false&&!scheduledAt.value)return '商家未到营业时间：'+store.value.opening_text;if(type.value==='DELIVERY'&&store.value.delivery_radius>0){const distance=distanceMeters(store.value,address.value);if(distance===null)return '请编辑收货地址并在地图上选择收货点';if(distance>store.value.delivery_radius)return '收货地址超出配送范围，可选择到店自取'}return ''});
async function loadCheckout(){pending.value=!!intents.read();loading.value=true;error.value='';try{if(pending.value){await recover(false);return}if(!cart.storeId)return;await ensureLogin();await memberIdentity();const [s,a,c,p]=await Promise.all([request('/stores/'+cart.storeId+'/info'),request('/addresses'),request('/coupons'),request('/catalog/products?'+queryString({storeId:cart.storeId,ids:cart.items.map(p=>p.id).join(','),pageSize:50}))]);store.value=s;slots.value=s.reservation_enabled?await request('/stores/'+cart.storeId+'/slots'):[];if(scheduledAt.value&&!slots.value.some(v=>v.value===scheduledAt.value))scheduledAt.value='';const fresh=reconcileCart(cart.items,p.rows||[]);cart.items=fresh.items;saveCart();if(fresh.changed)toast('菜品价格或库存已更新，请重新确认');const selected=uni.getStorageSync('food-selected-address');address.value=a.find(i=>i.id===selected)||a[0]||null;coupons.value=c.filter(i=>subtotal.value>=i.minimum);coupon.value=coupons.value.find(i=>i.id===coupon.value?.id)||null}catch(e){store.value={};error.value=e.message}finally{loading.value=false}}onShow(loadCheckout);
function chooseCoupon(){const options=['不使用优惠券',...coupons.value.map(c=>c.title+' −¥'+money(c.amount))];uni.showActionSheet({itemList:options,success:r=>coupon.value=r.tapIndex?coupons.value[r.tapIndex-1]:null})}
async function submit(){if(pending.value)return recover(true);if(busy.value||loading.value||!store.value.id||!cart.items.length)return;if(blocked.value)return toast(blocked.value);if(type.value==='DELIVERY'&&!address.value)return toast('请先添加收货地址');busy.value=true;error.value='';try{const body={storeId:cart.storeId,type:type.value,addressId:type.value==='DELIVERY'?address.value.id:null,couponId:coupon.value?.id||null,expectedTotal:total.value,remark:remark.value,scheduledAt:scheduledAt.value||null,items:cart.items.map(p=>({productId:p.id,quantity:p.quantity,specId:p.specId||null,addonIds:p.addonIds||[]}))};const serialized=JSON.stringify(body);if(lastBody&&lastBody!==serialized)requestKey=key();lastBody=serialized;const payload={...body,requestKey};intents.begin(state.memberId,payload,cartSignature(cart));pending.value=true;const order=await request('/orders','POST',payload,true);openConfirmedOrder(order)}catch(e){if(e.code===601)intents.rejected(state.memberId,requestKey);error.value=e.message}finally{pending.value=!!intents.read();busy.value=false}}
</script>
<style scoped>.address{border-top:5rpx solid #9eaf87}.item{display:flex;align-items:center;gap:20rpx;margin-bottom:24rpx;font-size:26rpx}.item image{width:95rpx;height:95rpx;border-radius:14rpx}.item-copy{flex:1}.item-copy .small{margin-top:10rpx}.coupon-row{padding:28rpx 0;font-size:26rpx}.remark{width:100%;height:125rpx;margin-top:20rpx;font-size:26rpx;line-height:1.6}</style>
